(function () {
  function getCookie(name) {
    return document.cookie
      .split(";")
      .map(function (item) { return item.trim(); })
      .filter(function (item) { return item.indexOf(name + "=") === 0; })
      .map(function (item) { return decodeURIComponent(item.slice(name.length + 1)); })[0] || "";
  }

  function triggerResponseError(element, response) {
    document.body.dispatchEvent(new CustomEvent("htmx:responseError", {
      detail: { elt: element, xhr: response }
    }));
  }

  function swap(target, html, mode) {
    if (!target) {
      return;
    }
    if (mode === "outerHTML") {
      target.outerHTML = html;
      bindAll();
      return;
    }
    target.innerHTML = html;
    bindAll();
  }

  function request(element) {
    var method = element.hasAttribute("hx-post") ? "POST" : "GET";
    var url = element.getAttribute("hx-post") || element.getAttribute("hx-get");
    var targetSelector = element.getAttribute("hx-target");
    var target = targetSelector ? document.querySelector(targetSelector) : element;
    var swapMode = element.getAttribute("hx-swap") || "innerHTML";
    var options = {
      method: method,
      headers: { "HX-Request": "true" }
    };

    if (method === "POST") {
      options.body = new FormData(element);
      options.headers["X-CSRFToken"] = getCookie("csrftoken");
    } else {
      var params = new URLSearchParams(new FormData(element));
      url = params.toString() ? url + "?" + params.toString() : url;
    }

    fetch(url, options)
      .then(function (response) {
        if (!response.ok) {
          triggerResponseError(element, response);
        }
        return response.text();
      })
      .then(function (html) {
        swap(target, html, swapMode);
      })
      .catch(function (error) {
        triggerResponseError(element, error);
      });
  }

  function bindForm(form) {
    if (form.dataset.hxBound === "true") {
      return;
    }
    form.dataset.hxBound = "true";
    var timer = null;
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      request(form);
    });
    form.querySelectorAll("input, select, textarea").forEach(function (field) {
      field.addEventListener("keyup", function () {
        if (!form.hasAttribute("hx-get")) {
          return;
        }
        clearTimeout(timer);
        timer = setTimeout(function () { request(form); }, 400);
      });
      field.addEventListener("change", function () {
        if (form.hasAttribute("hx-get")) {
          request(form);
        }
      });
    });
  }

  function bindAll() {
    document.querySelectorAll("form[hx-get], form[hx-post]").forEach(bindForm);
  }

  document.addEventListener("DOMContentLoaded", bindAll);
})();
